SELECT 
FROM moment m
LEFT JOIN app_user u ON m.user_id = u.id


        AND m.user_id = #{userId}


        AND m.content LIKE CONCAT('%', #{content}, '%')


        AND m.type = #{type}


        AND m.visibility = #{visibility}


        AND m.is_deleted = #{isDeleted}


        AND m.create_time >= #{beginTime}


        AND m.create_time <= #{endTime}


ORDER BY m.create_time DESC

